// @line-base pages/ListPage
'use client';
import Link from "next/link";
import { useState } from "react";
import { ListPage } from "../../../library/pages/ListPage";
import { Select } from "../../../library/components/Select";
import { TextField } from "../../../library/components/TextField";
import products from "../../../library/fixtures/products.json";

const categories = ["Clothing", "Home", "Electronics"];

export function CatalogPage() {
  const [category, setCategory] = useState("all");
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();
  const shown = products.filter(
    (p) => (category === "all" || p.category === category) && p.name.toLowerCase().includes(q),
  );
  return (
    <ListPage
      title="Products"
      toolbar={
        <>
          <Select
            label="Category"
            value={category}
            onValueChange={setCategory}
            options={[{ value: "all", label: "All" }, ...categories.map((c) => ({ value: c, label: c }))]}
          />
          <TextField label="Search" value={query} onChange={setQuery} />
        </>
      }
      empty={<p>No products found</p>}
    >
      {shown.length > 0
        ? shown.map((p) => (
            <article key={p.id} className="flex flex-col gap-2 rounded-lg border border-slate-200 p-4 shadow-sm">
              <p className="text-xs uppercase tracking-wide text-slate-500">{p.category}</p>
              <h2 className="text-lg font-semibold">
                <Link href={`/products/${p.id}`}>{p.name}</Link>
              </h2>
              <p>{`$${p.price.toFixed(2)}`}</p>
            </article>
          ))
        : undefined}
    </ListPage>
  );
}

import products from "../fixtures/products.json";

export type Product = (typeof products)[number];
export type CartLine = { id: string; quantity: number };
export type CartDetail = { product: Product; quantity: number; lineTotal: number };
export type CartTotals = { lines: CartDetail[]; itemCount: number; subtotal: number; shipping: number; total: number };

const KEY = "line-cart";
let current: CartLine[] | null = null;
const listeners = new Set<() => void>();

function load(): CartLine[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as CartLine[]) : [];
  } catch {
    return [];
  }
}

function commit(next: CartLine[]): void {
  current = next;
  try {
    window.localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // storage unavailable: the cart still works until the page is reloaded
  }
  listeners.forEach((listener) => listener());
}

export function getCart(): CartLine[] {
  if (current === null) current = load();
  return current;
}

export function subscribeCart(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function addToCart(id: string, quantity: number): void {
  const lines = getCart();
  const found = lines.some((line) => line.id === id);
  commit(
    found
      ? lines.map((line) => (line.id === id ? { ...line, quantity: line.quantity + quantity } : line))
      : [...lines, { id, quantity }],
  );
}

export function setQuantity(id: string, quantity: number): void {
  const lines = getCart();
  commit(
    quantity <= 0
      ? lines.filter((line) => line.id !== id)
      : lines.map((line) => (line.id === id ? { ...line, quantity } : line)),
  );
}

export function removeFromCart(id: string): void {
  commit(getCart().filter((line) => line.id !== id));
}

export function clearCart(): void {
  commit([]);
}

export function cartTotals(lines: CartLine[] = getCart()): CartTotals {
  const detailed: CartDetail[] = [];
  for (const line of lines) {
    const product = products.find((p) => p.id === line.id);
    if (product) detailed.push({ product, quantity: line.quantity, lineTotal: product.price * line.quantity });
  }
  const itemCount = detailed.reduce((n, d) => n + d.quantity, 0);
  const subtotal = Math.round(detailed.reduce((sum, d) => sum + d.lineTotal, 0) * 100) / 100;
  const shipping = subtotal >= 100 ? 0 : 5;
  return { lines: detailed, itemCount, subtotal, shipping, total: subtotal + shipping };
}

import { cartTotals, clearCart } from "./cart";

export type OrderDetails = { name: string; email: string; address: string; city: string; postalCode: string };
export type PlacedOrder = {
  number: string;
  buyer: string;
  lines: { name: string; quantity: number; lineTotal: number }[];
  total: number;
};

let lastOrder: PlacedOrder | null = null;

/** Mock order service: no network. Takes the cart, clears it and keeps the order for the confirmation page. */
export function placeOrder(details: OrderDetails): PlacedOrder {
  const totals = cartTotals();
  const order: PlacedOrder = {
    number: String(Date.now()).slice(-6),
    buyer: details.name,
    lines: totals.lines.map((d) => ({ name: d.product.name, quantity: d.quantity, lineTotal: d.lineTotal })),
    total: totals.total,
  };
  lastOrder = order;
  clearCart();
  return order;
}

export function getLastOrder(): PlacedOrder | null {
  return lastOrder;
}

// @line-base pages/DetailPage
'use client';
import Link from "next/link";
import { useParams } from "next/navigation";
import { useState } from "react";
import { DetailPage } from "../../../library/pages/DetailPage";
import { Button } from "../../../library/components/Button";
import { TextField } from "../../../library/components/TextField";
import { addToCart } from "../../../library/services/cart";
import products from "../../../library/fixtures/products.json";

export function ProductPage() {
  const params = useParams<{ id: string }>();
  const product = products.find((p) => p.id === params.id);
  const [quantity, setQuantity] = useState("1");
  const [added, setAdded] = useState(false);
  const back = (
    <Link href="/" className="text-sm underline">
      Back to products
    </Link>
  );
  if (!product) {
    return (
      <DetailPage title="Product not found" back={back}>
        <p>We could not find that product.</p>
      </DetailPage>
    );
  }
  const count = Math.max(1, Math.floor(Number(quantity) || 1));
  return (
    <DetailPage
      title={product.name}
      back={back}
      aside={
        <>
          <p className="text-xl font-semibold">{`$${product.price.toFixed(2)}`}</p>
          <TextField
            label="Quantity"
            type="number"
            min={1}
            value={quantity}
            onChange={(v) => {
              setQuantity(v);
              setAdded(false);
            }}
          />
          <Button
            label="Add to cart"
            onClick={() => {
              addToCart(product.id, count);
              setAdded(true);
            }}
          />
          {added ? <p role="status">Added to cart</p> : null}
        </>
      }
    >
      <p className="text-sm uppercase tracking-wide text-slate-500">{product.category}</p>
      <p>{product.description}</p>
    </DetailPage>
  );
}

