// @line-base pages/FormPage
'use client';
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useSyncExternalStore } from "react";
import { FormPage } from "../../../library/pages/FormPage";
import { Button } from "../../../library/components/Button";
import { TextField } from "../../../library/components/TextField";
import { cartTotals, getCart, subscribeCart, setQuantity, removeFromCart, type CartLine } from "../../../library/services/cart";

const NO_LINES: CartLine[] = [];
const money = (n: number) => `$${n.toFixed(2)}`;

export function CartPage() {
  const router = useRouter();
  const lines = useSyncExternalStore(subscribeCart, getCart, () => NO_LINES);
  const totals = cartTotals(lines);
  if (totals.lines.length === 0) {
    return (
      <main className="flex flex-col gap-4">
        <h1 className="text-2xl font-bold">Your cart</h1>
        <p>Your cart is empty</p>
        <Link href="/" className="text-sm underline">
          Continue shopping
        </Link>
      </main>
    );
  }
  return (
    <FormPage
      title="Your cart"
      submitLabel="Checkout"
      onSubmit={() => router.push("/checkout")}
      aside={
        <div className="flex flex-col gap-2 text-sm">
          <p className="flex justify-between">
            <span>Subtotal</span>
            <span>{money(totals.subtotal)}</span>
          </p>
          <p className="flex justify-between">
            <span>Shipping</span>
            <span>{money(totals.shipping)}</span>
          </p>
          <p className="flex justify-between font-semibold">
            <span>Total</span>
            <span>{money(totals.total)}</span>
          </p>
        </div>
      }
    >
      {totals.lines.map((d) => (
        <div key={d.product.id} className="flex flex-wrap items-end gap-4 border-b border-slate-200 pb-4">
          <div className="flex-1">
            <p className="font-medium">{d.product.name}</p>
            <p className="text-sm text-slate-600">{`${money(d.product.price)} each`}</p>
          </div>
          <TextField
            label={`Quantity for ${d.product.name}`}
            type="number"
            min={0}
            value={String(d.quantity)}
            onChange={(v) => setQuantity(d.product.id, Number(v) || 0)}
          />
          <p className="w-24 text-right">{money(d.lineTotal)}</p>
          <Button variant="ghost" label={`Remove ${d.product.name}`} onClick={() => removeFromCart(d.product.id)} />
        </div>
      ))}
    </FormPage>
  );
}

