// @line-base pages/FormPage
'use client';
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, useSyncExternalStore } from "react";
import { FormPage } from "../../../library/pages/FormPage";
import { TextField } from "../../../library/components/TextField";
import { Checkbox } from "../../../library/components/Checkbox";
import { cartTotals, getCart, subscribeCart, type CartLine } from "../../../library/services/cart";
import { placeOrder } from "../../../library/services/orders";

const NO_LINES: CartLine[] = [];
const money = (n: number) => `$${n.toFixed(2)}`;

type Form = { name: string; email: string; address: string; city: string; postalCode: string; terms: boolean };
type Errors = Partial<Record<keyof Form, string>>;

const EMPTY: Form = { name: "", email: "", address: "", city: "", postalCode: "", terms: false };

function check(f: Form): Errors {
  const errors: Errors = {};
  if (!f.name.trim()) errors.name = "Full name is required";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email.trim())) errors.email = "Enter a valid email";
  if (!f.address.trim()) errors.address = "Address is required";
  if (!f.city.trim()) errors.city = "City is required";
  if (!/^\d{5}$/.test(f.postalCode.trim())) errors.postalCode = "Postal code must be 5 digits";
  if (!f.terms) errors.terms = "Accept the terms to continue";
  return errors;
}

export function CheckoutPage() {
  const router = useRouter();
  const lines = useSyncExternalStore(subscribeCart, getCart, () => NO_LINES);
  const totals = cartTotals(lines);
  const [form, setForm] = useState<Form>(EMPTY);
  const [errors, setErrors] = useState<Errors>({});
  const [placed, setPlaced] = useState(false);

  const set = <K extends keyof Form>(key: K, value: Form[K]) => {
    setForm((f) => ({ ...f, [key]: value }));
    setErrors((e) => ({ ...e, [key]: undefined }));
  };

  const submit = () => {
    const found = check(form);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    setPlaced(true);
    placeOrder({
      name: form.name.trim(),
      email: form.email.trim(),
      address: form.address.trim(),
      city: form.city.trim(),
      postalCode: form.postalCode.trim(),
    });
    router.push("/order/confirmation");
  };

  if (!placed && totals.lines.length === 0) {
    return (
      <main className="flex flex-col gap-4">
        <h1 className="text-2xl font-bold">Checkout</h1>
        <p>Your cart is empty</p>
        <Link href="/" className="text-sm underline">
          Back to products
        </Link>
      </main>
    );
  }

  return (
    <FormPage
      title="Checkout"
      submitLabel="Place order"
      onSubmit={submit}
      aside={
        <div className="flex flex-col gap-2 text-sm">
          <p className="font-semibold">Order summary</p>
          {totals.lines.map((d) => (
            <p key={d.product.id} className="flex justify-between gap-2">
              <span>{`${d.product.name} × ${d.quantity}`}</span>
              <span>{money(d.lineTotal)}</span>
            </p>
          ))}
          <p className="flex justify-between font-semibold">
            <span>Total</span>
            <span>{money(totals.total)}</span>
          </p>
        </div>
      }
    >
      <TextField label="Full name" value={form.name} onChange={(v) => set("name", v)} error={errors.name} />
      <TextField label="Email" type="email" value={form.email} onChange={(v) => set("email", v)} error={errors.email} />
      <TextField label="Address" value={form.address} onChange={(v) => set("address", v)} error={errors.address} />
      <TextField label="City" value={form.city} onChange={(v) => set("city", v)} error={errors.city} />
      <TextField label="Postal code" value={form.postalCode} onChange={(v) => set("postalCode", v)} error={errors.postalCode} />
      <Checkbox label="I accept the terms" checked={form.terms} onCheckedChange={(v) => set("terms", v)} error={errors.terms} />
    </FormPage>
  );
}

