  const order = getLastOrder();
  if (!order) {
    return (
      <DetailPage title="Thank you for your order">
        <p>No recent order.</p>
        <Link href="/" className="text-sm underline">
          Continue shopping
        </Link>
      </DetailPage>
    );
  }
  return (
    <DetailPage title="Thank you for your order">
      <p className="font-medium">{`Order #${order.number}`}</p>
      <ul className="flex flex-col gap-1">
        {order.lines.map((l) => (
          <li key={l.name}>{`${l.name} × ${l.quantity} (${`$${l.lineTotal.toFixed(2)}`})`}</li>
        ))}
      </ul>
      <p className="font-semibold">{`Total paid: $${order.total.toFixed(2)}`}</p>
      <Link href="/" className="text-sm underline">
        Continue shopping
      </Link>
    </DetailPage>
  );
}

